describe('DesignSystemsService', () => {
  const create = jest.fn();
  const save = jest.fn();
  const find = jest.fn();
  const findOne = jest.fn();
  const remove = jest.fn();
  const repository = {
    create,
    save,
    find,
    findOne,
    remove,
  } as unknown as Repository<DesignSystem>;
  const deleteDesignSystemConfiguration = jest
